def sort_wide_blocks(grid, gap=2):
    """Reorder the double-column blocks (cols s*k, s*k+1, s=gap+1) by their count of nonzero cells, ascending; the single gap columns between blocks stay in place."""
    h, w = len(grid), len(grid[0])
    s = gap + 1
    n = (w + gap) // s
    order = sorted(range(n), key=lambda k: sum(1 for r in range(h) if grid[r][s*k+1] != 0))
    out = [[0]*w for _ in range(h)]
    for newk, k in enumerate(order):
        for c in (s*k, s*k+1):
            for r in range(h):
                out[r][s*newk + c - s*k] = grid[r][c]
        if s*k + gap < w and s*newk + gap < w:
            for r in range(h):
                out[r][s*newk + gap] = grid[r][s*k + gap]
    return out

